n("מיקאלה", "מיקאלה היא צורה נשית של מיכאל, שמקובלת באנגלית ובשפות של אירופה. השם מיכאל בא מהעברית, והוא בנוי משלוש מילים, מי, כ ואל, ופירושו מי כמו האל. בעברית צורת הנקבה היא מיכאלה, ומיקאלה נשמע כמעט אותו דבר.", ["מיכאל", "מיכאלה"])
n("מרווה", "מרווה היא שיח ריחני ממשפחת השפתניים, שהעלים שלו אפורים ורכים כמו קטיפה. בארץ גדלים כמה מינים של מרווה בר, ואחד מהם, המרווה המשולשת, נפוץ בהרים של הגליל ושל יהודה. בערבית קוראים לצמח מרמייה, ומהעלים שלו מכינים חליטה.")
n("מריאם", "מריאם היא הצורה הערבית של מרים, והיא מוכרת בקהילות מוסלמיות ונוצריות כאחד. בתורה מרים היא אחות של משה ושל אהרן, והיא נקראת הנביאה. הפירוש של השם לא ברור, ויש שקושרים אותו למילה מר או למילה מרי, אבל אין על כך הסכמה.", ["מרים"])
n("מריאן", "מריאן היא צורה צרפתית של השם מרים, שהגיעה לאירופה דרך הצורה הלטינית מריה. בצרפתית השם נכתב מריאן, ובשפות אחרות של אירופה מוכרת גם הצורה מריאנה. בעברית השם נשמע כמעט אותו דבר כמו בצרפתית.", ["מרים", "מריאנה"])
n("מתיא", "מתיא היא צורה ארמית קצרה של מתתיהו, והיא מוכרת כבר מימי המשנה והתלמוד. מתתיהו בנוי מהמילה מתת, מתנה, ומהסיומת יהו, צורה של שם ה׳. באותה דרך נבנו גם מתן ומתניה. ביוונית השם נשמע מתתיאס, וממנו באו מתיו באנגלית ומתיאס בגרמנית.", ["מתי", "מתתיהו"])
n("נאדרה", "נאדרה היא צורת הנקבה של השם הערבי נאדר, ופירושה נדירה, דבר שקשה למצוא. המילה באה מהשורש הערבי נ־ד־ר, שעניינו מיעוט וייחוד. בעברית של היום המילה נדיר נשמעת קרובה מאוד, והמשמעות שלה דומה.", ["נאדר"])
n("נאילה", "נאילה היא צורת הנקבה של השם הערבי נאיל, ופירושה מי שמשיגה את מה שרצתה. המילה באה מהשורש הערבי נ־י־ל, שעניינו השגה וקבלה של דבר טוב. כשם, נאילה מביא את הרעיון של הצלחה ושל מטרה שהושגה.", ["נאיל"])
n("נבילה", "נבילה היא צורת הנקבה של השם הערבי נביל, ופירושה אצילה, בעלת נפש נדיבה ומכובדת. המילה באה מהשורש הערבי נ־ב־ל, ובערבית של היום היא מתארת גם התנהגות הוגנת ומכובדת. כשם, נבילה מביא את הרעיון של כבוד ושל נדיבות.", ["נביל"])
n("נג'ד", "נג'ד היא מילה ערבית שפירושה רמה, אדמה גבוהה ושטוחה שמתנשאת מעל הסביבה. בשם הזה נקרא האזור הגדול שבמרכז חצי האי ערב, שרובו רמה מדברית רחבה. כשם, נג'ד מביא תמונה של מרחב פתוח וגבוה, ושל אופק רחוק.")
n("נדיה", "נדיה היא צורת חיבה רוסית של השם נדז'דה, שפירושו תקווה. מהרוסית השם עבר לשפות נוספות, ובצרפתית נבנתה ממנו צורת החיבה נדין. נאדיה הוא כתיב אחר של השם, ובערבית הוא נשמע כמעט אותו דבר, אבל שם הוא קשור למילה נדא, טל.", ["נדין", "נאדיה"])
n("נוב", "נוב היא עיר מקראית קטנה בנחלת בנימין, לא רחוק מירושלים, שבה ישבו כהנים בימי שאול ודוד. מקום העיר לא ידוע בדיוק, ויש שמזהים אותו עם אחת הגבעות שמצפון לירושלים. השם נשמע כמו השורש נ־ו־ב, שממנו באה המילה תנובה, פרי ויבול.")
n("נופר", "נופר הוא צמח מים, שהעלים העגולים שלו צפים על פני המים, והפרחים שלו נפתחים מעליהם. בארץ גדל בר הנופר הצהוב, בעיקר בעמק החולה, והוא נדיר מאוד היום. המילה נופר הגיעה לעברית מהערבית, ובערבית היא באה מהפרסית.")
n("ניקול", "ניקול היא צורת הנקבה הצרפתית של ניקולא, שם שבא מהיוונית ובנוי משתי מילים, ניצחון ועם. השם מוכר בשפות רבות של אירופה, ובאיטלקית מוכרת הצורה ניקולטה. באנגלית ובצרפתית השם נכתב כמעט אותו דבר, ובעברית מקובל לכתוב אותו עם האות ו.")
n("נמרוד", "נמרוד הוא שם מקראי, ובתורה הוא מתואר כגיבור ציד וכמלך שראשית ממלכתו בבבל, בארץ שנער. הפירוש של השם לא ברור, ויש שקושרים אותו לשורש מ־ר־ד. ברמת הגולן, למרגלות החרמון, עומד מבצר נמרוד, מבצר מימי הביניים שהמסורת המקומית קשרה לשמו.")
n("נתיב", "נתיב היא מילה עברית קדומה לשביל ולדרך, והיא מופיעה כבר בתנ״ך, בעיקר בשירה. מאותו שורש, נ־ת־ב, באה גם המילה נתיבה. בעברית של היום משתמשים בה גם לתיאור של נתיב בכביש ושל נתיב טיסה, וגם במובן של כיוון בחיים.")
n("סאמח", "סאמח הוא שם ערבי מהשורש ס־מ־ח, שעניינו סליחה ונדיבות, ופירושו מי שסולח ונותן ביד רחבה. מאותו שורש באה בערבית המילה סמאח, סליחה, שמשמשת גם בדיבור היומיומי. השורש נשמע כמו המילה העברית שמח, אבל המשמעות שלו בערבית שונה.")
n("סוזאן", "סוזאן היא צורה אירופית של השם העברי שושנה, שהגיע לשפות של אירופה דרך היוונית והלטינית, שבהן הוא נשמע סוזנה. השם מוכר בצרפתית ובאנגלית, ובערבית הוא מוכר בצורה סוזאן. המילה שושנה עצמה היא שם של פרח, ויש שמזהים אותו עם השושן הצחור.", ["שושנה"])
n("סטערנא", "סטערנא הוא שם יידי שבא מהמילה היידית שטערן, כוכב, שקרובה למילה הגרמנית שטרן. הכתיב שומר על הדרך שבה נכתבים שמות ביידיש, עם האות ע במקום התנועה. ביידיש מוכרת גם הצורה שטערנא, עם האות ש בהתחלה.")
n("סלטאן", "סלטאן הוא כתיב של המילה הערבית סולטאן, שפירושה שלטון וכוח, ובהמשך היא נעשתה תואר של שליט. המילה נכנסה לערבית מהארמית, שבה שולטנא פירושו שלטון. מאותו שורש באות בעברית המילים שליט ושלטון.", ["סולטאן"])
n("עדה", "עדה היא שם מקראי עתיק, ובתורה זה שמן של שתי נשים, אחת מהן אשתו של למך. השם קשור למילה עדי, תכשיט וקישוט, כל מה שעונדים לנוי. בעברית של היום המילה עדה מתארת גם קהילה, קבוצה של אנשים שיש להם מסורת משותפת.")
n("עומראן", "עומראן היא מילה ערבית שפירושה מקום מיושב ובנוי, שיש בו חיים. היא באה מהשורש הערבי ע־מ־ר, שעניינו חיים ובנייה של מקום. בכתב הערבי עומראן נכתב באותן אותיות כמו עמראן, הצורה הערבית של עמרם, ויש שרואים בשני השמות שתי הגיות של אותו שם.", ["עמראן", "עמרם"])
n("עימנואל", "עימנואל הוא כתיב של השם העברי עמנואל, שבנוי מהמילה עמנו, איתנו, ומהמילה אל. הכתיב עם האות י מסמן את התנועה בהברה הראשונה, כמו בדיבור. השם מוכר בשפות רבות, כמו עמנואל בצרפתית ומנואל בשפה הספרדית ובפורטוגזית.", ["עמנואל", "עמנואלה", "מנואל"])
n("עמיה", "עמיה בנוי מהמילה עם ומהסיומת יה, צורה קצרה של שם ה׳, ופירושו העם של ה׳. באותה דרך נבנו בעברית גם עמיאל ועמיחי, שמחברים את המילה עמי לשם האל או למילה חי. המילה עם מתארת בעברית ציבור של אנשים שיש להם שפה ומסורת משותפות.")
n("ענבל", "ענבל הוא הלשון הקטנה שתלויה בתוך פעמון, ומכה בדפנות שלו כדי ליצור את הצלצול. המילה מוכרת כבר מלשון חכמים, ובעברית של היום היא משמשת גם לתיאור של הלשונית הקטנה שבגרון. כשם, ענבל מביא תמונה של צליל צלול ונעים.")
n("עקאב", "עקאב היא המילה הערבית לעוף דורס גדול, ובעברית מתרגמים אותה נשר או עיט. העוף הזה בונה את הקן שלו על צוקים גבוהים, וצד מגובה רב בעזרת הראייה החדה שלו. כשם, עקאב מביא תמונה של מעוף גבוה ושל מבט רחב מלמעלה.")
n("פואז", "פואז הוא שם ערבי מהשורש פ־ו־ז, שעניינו ניצחון והצלחה, ופירושו מי שמנצח שוב ושוב. מאותו שורש באים בערבית גם השמות פאיז ופאוזי, וגם המילה פוז, ניצחון. כשם, פואז מביא את הרעיון של הצלחה ושל השגת מטרה.")
n("פרג'", "פרג' היא מילה ערבית שפירושה הקלה, הרגע שבו צרה נגמרת ובא אחריה רווח. היא באה מהשורש הערבי פ־ר־ג', שעניינו פתיחה ושחרור. בערבית של היום המילה מוכרת גם בדיבור, כשמדברים על סוף של תקופה קשה.")
n("פרדוס", "פרדוס היא המילה הערבית לגן עדן, והיא באה מהמילה הפרסית העתיקה לגן מוקף חומה. מאותה מילה פרסית באה גם המילה העברית פרדס, מטע של עצי פרי, וגם המילה היוונית שממנה בא פרדייס באנגלית. כשם, פרדוס מביא תמונה של גן ירוק ופורח.")
n("פרידה", "פרידה הוא שם שבא מהמילה הגרמנית לשלום, והוא מוכר גם כצורה קצרה של שמות ארוכים יותר, כמו פרידריקה. ביידיש השם נכתב גם פרידא, והוא היה מוכר בקהילות אשכנז. השם מוכר בשפות רבות של אירופה, ובכל אחת הוא נשמע מעט אחרת.", ["פרידא"])
n("פרל", "פרל הוא שם שבא מהמילה לפנינה, ביידיש ובאנגלית. ביידיש השם היה מוכר בקהילות אשכנז, והוא נכתב עם האות ע, פערל. באנגלית המילה מתארת גם צבע לבן ומבריק, כמו הברק של פנינה, ובעברית אותו רעיון בא לידי ביטוי בשם פנינה.", ["פערל"])
n("צוריאל", "צוריאל בנוי מהמילה צור, סלע, ומהמילה אל, ופירושו שהאל הוא הסלע שלי, מקור של כוח ויציבות. בתורה צוריאל הוא נשיא של משפחות מררי, משבט לוי. המילה צור מתארת בעברית סלע קשה וחזק, ומאותה מילה נבנו גם השמות צור וצורי.", ["צור", "צורי"])
n("קלואי", "קלואי הוא שם יווני עתיק, שפירושו נבט ירוק וצעיר, כמו הצמח שעולה באביב. השם מוכר בצרפתית ובאנגלית, ובצרפתית הוא נכתב קלואה. מאותו שורש יווני באה גם המילה כלורופיל, החומר שנותן לצמחים את הצבע הירוק.")
n("קמיל", "קמיל הוא הצורה הצרפתית של השם הלטיני קמילוס, שם משפחה רומי עתיק. בצרפתית השם ניתן לבנים ולבנות, ובשפות אחרות של אירופה מוכרות הצורות קמילה וקמילו. בעברית השם נכתב עם האות י, כדי לסמן את התנועה בהברה השנייה.", ["קמילה"])
n("ראני", "ראני הוא שם ערבי מהשורש ר־נ־ו, שעניינו הבטה ממושכת, ופירושו מי שמביט ומסתכל בעיון. מאותו שורש באה גם צורת הנקבה ראניה. בעברית השם נשמע כמו השם רני, מלשון רינה ושירה, אבל המקור שלו אחר.", ["ראניה"])
n("ראסם", "ראסם הוא שם ערבי מהשורש ר־ס־ם, שעניינו ציור ושרטוט, ופירושו מי שמצייר או מעצב. מאותו שורש באה בערבית המילה רסם, ציור, וגם המילה רסמי, רשמי. בעברית השורש ר־ש־ם קרוב אליו, כמו במילים רשימה ורושם.")
n("רוזא", "רוזא היא המילה הלטינית לוורד, וממנה באו שמות דומים בשפות רבות, כמו רוז באנגלית ובצרפתית ורוזה בשפות אחרות. ביידיש השם נשמע רויזא, והוא היה מוכר בקהילות אשכנז. הוורד הוא פרח עתיק, שמגדלים אותו בגינות כבר אלפי שנים.", ["רוז", "רוזה", "רויזא"])
n("רונה-לי", "רונה־לי הוא שם שנבנה בעברית החדשה משתי מילים, רונה ולי, ופירושו שיש לי רינה. המילה רונה באה מהשורש ר־נ־ן, שעניינו שירה ושמחה, ומאותו שורש באות גם המילים רינה ורננה. המקף מפריד בין שני חלקי השם, כדי שכל חלק יישמע לבד.")
n("רנן", "רנן בא מהשורש ר־נ־ן, שעניינו שירה בקול ושמחה, ומאותו שורש באות גם המילים רינה, רננה ורנה. השורש מוכר כבר בעברית הקדומה, בעיקר בשירה. כשם, רנן מביא תמונה של קול שמח ושל שירה משותפת.", ["רננה"])
n("רעכל", "רעכל היא צורה יידית של השם המקראי רחל, שפירושו בעברית כבשה. ביידיש השם נשמע רעכל, והאות ע מסמנת את התנועה, כמו בכתיב של היידיש. בקהילות אשכנז רעכל הייתה הצורה של רחל בדיבור היומיומי.", ["רחל"])
n("רפאלה", "רפאלה היא צורת הנקבה של רפאל, שם עברי שבנוי מהשורש ר־פ־א ומהמילה אל, ופירושו האל ריפא. מאותו שורש באות גם המילים רפואה ורופא. השם מוכר גם באיטלקית ובשפה הספרדית, שבהן הוא נכתב כמעט אותו דבר.", ["רפאל"])
n("רפעת", "רפעת היא מילה ערבית מהשורש ר־פ־ע, שעניינו הרמה והגבהה, ופירושה רוממות ומעמד גבוה. מאותו שורש באה בערבית גם המילה רפיע, נעלה ומכובד. כשם, רפעת מביא את הרעיון של כבוד ושל מקום גבוה.")
n("שאכר", "שאכר הוא שם ערבי מהשורש ש־כ־ר, שעניינו תודה והכרת טובה, ופירושו מי שמודה. מאותו שורש באה המילה שוכראן, תודה, שמשמשת בערבית בדיבור היומיומי. כשם, שאכר מביא את הרעיון של הכרה במה שיש ושל תודה עליו.")
n("שאשא", "שאשא היא צורת חיבה רוסית של אלכסנדר ושל אלכסנדרה, וברוסית היא ניתנת לבנים ולבנות. אלכסנדר הוא שם יווני שבנוי משתי מילים, להגן ואנשים, ופירושו מי שמגן על אנשים. ברוסית מקובל לבנות צורות חיבה קצרות לשמות ארוכים, ושאשא היא אחת מהן.", ["אלכסנדר", "אלכסנדרה"])
n("שביט", "שביט הוא גוף קטן של קרח ואבק שנע סביב השמש, וכשהוא מתקרב אליה נוצר מאחוריו זנב ארוך ומאיר. המילה שביט מוכרת כבר מלשון חכמים, ובארמית יש לה צורה דומה. כשם, שביט מביא תמונה של אור שחוצה את שמי הלילה.")
n("שדה", "שדה היא מילה עברית קדומה לאדמה פתוחה, שמגדלים בה תבואה או שיש בה מרעה. בעברית של היום המילה משמשת גם במובן רחב יותר, כמו שדה פרחים או שדה ראייה. כשם, שדה מביא תמונה של מרחב ירוק ופתוח, של טבע ושל אדמה.")
n("שראל", "שראל בנוי מהמילה שר, מי ששולט ומוביל, ומהמילה אל, ופירושו האל שולט. השורש ש־ר־ר קשור לשלטון ולמנהיגות, ומאותו שורש באות גם המילים שררה ושרה, נסיכה. באותה דרך נבנה גם השם שריה, עם הסיומת יה במקום אל.")
n("תיאודור", "תיאודור הוא שם יווני שבנוי משתי מילים, תיאוס, אל, ודורון, מתנה. במשמעות זו הוא קרוב מאוד לשמות העבריים נתנאל ומתתיהו, שגם הם מדברים על מתנה מהאל. צורות החיבה שלו הן תאו ותיאו, ובשפות של אירופה מוכרת גם צורת הנקבה תיאודורה.", ["תאו", "תיאו"])
n("תמארה", "תמארה היא צורה של השם המקראי תמר, שהגיעה לשפות של מזרח אירופה ושל הקווקז. בגאורגית ובשפה הרוסית השם נשמע תמרה, ובעברית הכתיב עם האות א מסמן את התנועה בהברה השנייה. התמר הוא עץ שגדל באזורים חמים ויבשים, והפרי שלו מתוק.", ["תמר", "תמרה"])
n("תמרי", "תמרי בנוי על המילה תמר, העץ שגדל בעמקים החמים של הארץ, עם הסיומת י, ופירושו התמר שלי. התמר גדל בארץ כבר אלפי שנים, והפירות שלו מתוקים ועשירים. באותה דרך נבנו גם תמרה ותומר.", ["תמר", "תומר", "תמרה"])
n("תקוה", "תקוה היא הכתיב הישן של המילה תקווה, ציפייה שיבוא דבר טוב. המילה מופיעה כבר בתנ״ך, ושם היא מתארת גם חבל או חוט, כי השורש ק־ו־ה קשור גם למתיחה של קו. בעברית של היום התקווה היא גם שם ההמנון של מדינת ישראל.")

